1	import { camera, createAuraApp, effects, environments, instances, lights, material, primitives, scene, type AuraTransformSpec } from "@aura3d/engine";
2	
3	// A night street: lantern posts with real point lights, glowing windows, a moon, fog and bloom.
4	// Emissive materials only look like light sources when bloom and fog give them a halo and depth.
5	const lampSpots: Array<[number, number]> = [[-4, 6], [-4, -2], [-4, -10], [4, 2], [4, -6], [4, -14]];
6	const warmWindows: AuraTransformSpec[] = [];
7	const coolWindows: AuraTransformSpec[] = [];
8	const towers: AuraTransformSpec[] = [];
9	let seed = 99;
10	const rand = (): number => ((seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0) / 4294967296);
11	
12	for (const side of [-1, 1]) for (let i = 0; i < 6; i += 1) {
13	  const x = side * 9.5, z = 8 - i * 6.5, h = 6 + rand() * 7;
14	  towers.push({ position: [x, h / 2, z], scale: [4.6, h, 5] });
15	  for (let row = 0; row < Math.floor(h / 1.6); row += 1) for (let col = 0; col < 2; col += 1) {
16	    if (rand() < 0.35) continue; // dark windows
17	    (rand() < 0.7 ? warmWindows : coolWindows).push({ position: [x - side * 2.33, 1.2 + row * 1.5, z - 1.1 + col * 2.2], scale: [0.04, 0.7, 0.9] });
18	  }
19	}
20	
21	const stage = scene({ background: "#05070d" })
22	  .add(environments.neutral({ intensity: 0.25, background: false }))
23	  .add(lights.directional({ name: "moonlight", position: [-10, 16, -10], target: [0, 0, -4], intensity: 1.1, color: "#7d9bff", shadow: true }))

